<?php
namespace App\Http\Controllers\Api\Budget; use App\Http\Controllers\Controller; use App\Models\Budget\BudgetReallocation; use App\Services\Budget\BudgetMonitoringService; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
class BudgetReallocationController extends Controller { public function index(){return response()->json(['success'=>true,'data'=>BudgetReallocation::with('fromLine','toLine')->latest()->get()]);} public function store(Request $r){$d=$r->validate(['project_id'=>'nullable|exists:projects,id','from_budget_line_id'=>'required|different:to_budget_line_id|exists:budget_lines,id','to_budget_line_id'=>'required|exists:budget_lines,id','amount'=>'required|numeric|min:0.01','reason'=>'required|string']); return response()->json(['success'=>true,'data'=>BudgetReallocation::create([...$d,'reference'=>'BR-'.now()->format('YmdHis'), 'created_by'=>$r->user()->id])],201);} public function submit(Request $r,BudgetReallocation $budgetReallocation){if($budgetReallocation->status!=='draft')throw ValidationException::withMessages(['status'=>'Only draft may be submitted.']);$budgetReallocation->update(['status'=>'submitted','submitted_by'=>$r->user()->id,'submitted_at'=>now()]);return response()->json(['success'=>true,'data'=>$budgetReallocation]);} public function approve(Request $r,BudgetReallocation $budgetReallocation,BudgetMonitoringService $budget){if($budgetReallocation->status!=='submitted')throw ValidationException::withMessages(['status'=>'Only submitted may be approved.']);$available=$budget->validate($budgetReallocation->from_budget_line_id,$budgetReallocation->amount);if(!$available['allowed'])throw ValidationException::withMessages(['amount'=>$available['message']]);DB::transaction(function()use($budgetReallocation,$r){$from=$budgetReallocation->fromLine()->lockForUpdate()->first();$to=$budgetReallocation->toLine()->lockForUpdate()->first();$from->decrement('total_amount',$budgetReallocation->amount);$to->increment('total_amount',$budgetReallocation->amount);$budgetReallocation->update(['status'=>'applied','approved_by'=>$r->user()->id,'approved_at'=>now(),'decision_notes'=>$r->input('notes')]);});return response()->json(['success'=>true,'data'=>$budgetReallocation->fresh()]);} }
